495	// Planning: compare files on disk against the ledger
496	// ---------------------------------------------------------------------------
497	
498	export interface LedgerRow {
499	  filename: string;
500	  checksum: string;
501	  applied_at?: Date | string | null;
502	  baselined?: boolean | null;
503	}
504	
505	export interface DriftRecord {
506	  filename: string;
507	  recordedChecksum: string;
508	  actualChecksum: string;
509	  appliedAt?: Date | string | null;
510	}
511	
512	export interface MigrationPlan {
513	  /** Every `*.sql` on disk, in apply order. */
514	  ordered: string[];
515	  /** Recorded and unchanged since. */
516	  applied: string[];
517	  /** On disk, never recorded — these are what a run would execute. */
518	  pending: string[];
519	  /** Recorded, but the file changed since. Fatal. */
520	  drifted: DriftRecord[];
521	  /** Recorded, but the file is gone from disk. Warning. */
522	  orphaned: string[];
523	  /** Pending files that sort before something already applied. Warning. */
524	  outOfOrder: string[];
525	}
526	
527	export function planMigrations(
528	  ordered: readonly string[],
529	  checksums: ReadonlyMap<string, string>,
530	  ledger: readonly LedgerRow[],
531	): MigrationPlan {
532	  const recorded = new Map<string, LedgerRow>();
533	  for (const row of ledger) recorded.set(row.filename, row);
534	
535	  const applied: string[] = [];
536	  const pending: string[] = [];
537	  const drifted: DriftRecord[] = [];
538	
539	  for (const filename of ordered) {
540	    const row = recorded.get(filename);
541	    if (!row) {
542	      pending.push(filename);
543	      continue;
544	    }
545	    const actual = checksums.get(filename);
546	    if (actual !== undefined && actual !== row.checksum) {
547	      drifted.push({
548	        filename,
549	        recordedChecksum: row.checksum,
550	        actualChecksum: actual,
551	        appliedAt: row.applied_at ?? null,
552	      });
553	      continue;
554	    }
555	    applied.push(filename);
556	  }
557	
558	  const onDisk = new Set(ordered);
559	  const orphaned = ledger
560	    .map((row) => row.filename)
561	    .filter((filename) => !onDisk.has(filename));
562	
563	  const lastApplied = [...applied, ...drifted.map((d) => d.filename)].sort((a, b) =>
564	    a < b ? -1 : a > b ? 1 : 0,
565	  ).pop();
566	  const outOfOrder =
567	    lastApplied === undefined
568	      ? []
569	      : pending.filter((filename) => filename < lastApplied);
570	
571	  return {
572	    ordered: [...ordered],
573	    applied,
574	    pending,
575	    drifted,
576	    orphaned: sortMigrationFiles(orphaned),
577	    outOfOrder,
578	  };
579	}
