581	/** Read every migration's checksum from disk. */
582	export function checksumAll(
583	  dir: string,
584	  filenames: readonly string[],
585	): Map<string, string> {
586	  const map = new Map<string, string>();
587	  for (const filename of filenames) {
588	    map.set(filename, checksumMigrationFile(dir, filename));
589	  }
590	  return map;
591	}
592	
593	export function describeDrift(drifted: readonly DriftRecord[]): string {
594	  return drifted
595	    .map(
596	      (d) =>
597	        `  • ${d.filename}\n` +
598	        `      recorded checksum : ${d.recordedChecksum}\n` +
599	        `      file checksum now : ${d.actualChecksum}\n` +
600	        `      recorded at       : ${d.appliedAt ?? "unknown"}`,
601	    )
602	    .join("\n");
603	}
604	
605	export class MigrationChecksumDriftError extends Error {
606	  readonly drifted: readonly DriftRecord[];
607	
608	  constructor(drifted: readonly DriftRecord[]) {
609	    super(
610	      `Migration checksum drift detected — ${drifted.length} already-applied ` +
611	        `migration file(s) changed after they were recorded as applied:\n` +
612	        `${describeDrift(drifted)}\n` +
613	        `Refusing to run. An applied migration file must be immutable: the ` +
614	        `database was changed by the OLD contents, so the new contents have ` +
615	        `never run anywhere. Fix by reverting the file, or by writing the ` +
616	        `change as a NEW migration. Only if you are certain the recorded row ` +
617	        `is wrong should you correct ${LEDGER_QUALIFIED} by hand.`,
618	    );
619	    this.name = "MigrationChecksumDriftError";
620	    this.drifted = drifted;
621	  }
622	}
623	export class MigrationHistoryError extends Error {
624	  constructor(message: string) {
625	    super(message);
626	    this.name = "MigrationHistoryError";
627	  }
628	}
