654	/** Serialize deploys for the full plan/apply/baseline operation. */
655	export async function withMigrationAdvisoryLock<T>(
656	  client: MigrationClient,
657	  work: () => Promise<T>,
658	): Promise<T> {
659	  await client.query(ACQUIRE_MIGRATION_LOCK_SQL);
660	  try {
661	    return await work();
662	  } finally {
663	    await client.query(RELEASE_MIGRATION_LOCK_SQL).catch(() => undefined);
