725	/**
726	 * Apply one migration: its statements plus the ledger row, in a single
727	 * transaction we own. The file's own BEGIN/COMMIT is stripped first.
728	 */
729	export async function applyMigration(
730	  client: MigrationClient,
731	  filename: string,
732	  source: string,
733	): Promise<{ statements: number; durationMs: number }> {
734	  const checksum = checksumMigrationSource(source);
735	  const statements = executableStatements(source);
736	  const startedAt = Date.now();
737	
738	  await client.query("BEGIN");
739	  try {
740	    for (const statement of statements) {
741	      try {
742	        await client.query(statement.raw);
743	      } catch (error) {
744	        throw new MigrationExecutionError(filename, statement.line, error);
745	      }
746	    }
747	    const durationMs = Date.now() - startedAt;
748	    await client.query(INSERT_LEDGER_SQL, [filename, checksum, durationMs, false]);
749	    await client.query("COMMIT");
750	    return { statements: statements.length, durationMs };
751	  } catch (error) {
752	    await client.query("ROLLBACK").catch(() => undefined);
753	    throw error;
754	  }
755	}
756	
757	export interface RunResult {
758	  plan: MigrationPlan;
759	  appliedNow: string[];
760	}
761	
762	export interface RunOptions {
763	  dir?: string;
764	  dryRun?: boolean;
765	  log?: (message: string) => void;
766	}
767	
768	/** Apply every pending migration, in order, aborting on the first failure. */
769	export async function runPendingMigrations(
770	  client: MigrationClient,
771	  options: RunOptions = {},
772	): Promise<RunResult> {
773	  const dir = options.dir ?? defaultMigrationsDir();
774	  const log = options.log ?? ((message: string) => console.log(message));
775	
776	  const ordered = listMigrationFiles(dir);
777	  const checksums = checksumAll(dir, ordered);
778	
779	  // Read without creating: a --dry-run must leave the database untouched.
780	  const ledger = (await readMigrationLedgerIfPresent(client)) ?? [];
781	  const plan = planMigrations(ordered, checksums, ledger);
782	
783	  if (plan.drifted.length > 0) throw new MigrationChecksumDriftError(plan.drifted);
784	
785	  if (plan.orphaned.length > 0) {
786	    throw new MigrationHistoryError(
787	      `${plan.orphaned.length} migration(s) recorded in ${LEDGER_QUALIFIED} ` +
788	        `have no file on disk: ${plan.orphaned.join(", ")}. Refusing to run ` +
789	        `until repository and database history agree.`,
790	    );
791	  }
792	  if (plan.outOfOrder.length > 0) {
793	    throw new MigrationHistoryError(
794	      `Out-of-order migration(s) pending: ${plan.outOfOrder.join(", ")}. ` +
795	        `Refusing to alter history; ship a new forward migration instead.`,
796	    );
797	  }
798	
799	  if (plan.pending.length === 0) {
800	    log(
801	      `✅ Nothing to apply — all ${plan.applied.length} migration(s) are ` +
802	        `already recorded in ${LEDGER_QUALIFIED}.`,
803	    );
804	    return { plan, appliedNow: [] };
805	  }
806	
807	  if (options.dryRun) {
808	    log(`Would apply ${plan.pending.length} migration(s):`);
809	    for (const filename of plan.pending) log(`  • ${filename}`);
810	    log("Dry run — nothing was executed.");
811	    return { plan, appliedNow: [] };
812	  }
813	
814	  await ensureMigrationLedger(client);
815	
816	  const appliedNow: string[] = [];
817	  for (const filename of plan.pending) {
818	    const source = readMigrationSource(dir, filename);
819	    log(`→ applying ${filename} ...`);
820	    const { statements, durationMs } = await applyMigration(client, filename, source);
821	    appliedNow.push(filename);
822	    log(`  ✅ ${filename} (${statements} statement(s), ${durationMs}ms)`);
823	  }
824	
825	  log(`✅ Applied ${appliedNow.length} migration(s).`);
826	  return { plan, appliedNow };
827	}
