832	
833	export class BaselineRefusedError extends Error {
834	  constructor(message: string) {
835	    super(message);
836	    this.name = "BaselineRefusedError";
837	  }
838	}
839	
840	export interface BaselineOptions extends RunOptions {
841	  /** Without this, baseline prints its plan and refuses. */
842	  confirm?: boolean;
843	  /** Allow baselining when the ledger already has rows. */
844	  force?: boolean;
845	  /** Injectable only so unit tests with synthetic migration names can opt in. */
846	  effectVerifier?: typeof findMissingBaselineEffects;
847	}
848	
849	export const COUNT_PUBLIC_TABLES_SQL = `SELECT count(*)::int AS count FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE'`;
850	
851	export async function countPublicTables(client: MigrationClient): Promise<number> {
852	  const result = await client.query<{ count: number }>(COUNT_PUBLIC_TABLES_SQL);
853	  return Number(result.rows[0]?.count ?? 0);
854	}
855	
856	/**
857	 * Record migrations as applied WITHOUT executing them, to adopt this runner on
858	 * a database that already has their effects.
859	 *
860	 * Guards, in order:
861	 *   1. `--confirm` must be passed explicitly (never a default).
862	 *   2. The `public` schema must already contain tables. Baselining an empty
863	 *      database would permanently skip the entire schema and leave a database
864	 *      that can never be built — this is the guard that matters most.
865	 *   3. The ledger must be empty, unless `--force`.
866	 */
867	export async function baselineMigrations(
868	  client: MigrationClient,
869	  options: BaselineOptions = {},
870	): Promise<{ plan: MigrationPlan; recorded: string[] }> {
871	  const dir = options.dir ?? defaultMigrationsDir();
872	  const log = options.log ?? ((message: string) => console.log(message));
873	
874	  const ordered = listMigrationFiles(dir);
875	  const checksums = checksumAll(dir, ordered);
876	
877	  // Read without creating: a refused baseline must leave no trace.
878	  const ledger = (await readMigrationLedgerIfPresent(client)) ?? [];
879	  const plan = planMigrations(ordered, checksums, ledger);
880	
881	  const toRecord = plan.pending;
882	
883	  log("");
884	  log(`Baseline plan for ${LEDGER_QUALIFIED}:`);
885	  log(
886	    `  ${toRecord.length} migration(s) would be RECORDED AS APPLIED WITHOUT ` +
887	      `BEING EXECUTED:`,
888	  );
889	  for (const filename of toRecord) log(`    • ${filename}`);
890	  if (plan.applied.length > 0) {
891	    log(`  ${plan.applied.length} already recorded: ${plan.applied.join(", ")}`);
892	  }
893	  log("");
894	
895	  if (toRecord.length === 0) {
896	    log("Nothing to baseline — every migration is already recorded.");
897	    return { plan, recorded: [] };
898	  }
899	
900	  if (!options.confirm) {
901	    throw new BaselineRefusedError(
902	      `Baseline NOT applied. This mode marks migrations as applied without ` +
903	        `running them and is only correct on a database that already has ` +
904	        `their effects. If the plan above is right, re-run with --confirm:\n` +
905	        `  npm run db:migrate:baseline -- --confirm`,
906	    );
907	  }
908	
909	  const tableCount = await countPublicTables(client);
910	  if (tableCount === 0) {
911	    throw new BaselineRefusedError(
912	      `Refusing to baseline: the "public" schema of this database contains no ` +
913	        `tables, so it cannot already have the effects of ${toRecord.length} ` +
914	        `migration(s). Baselining here would permanently skip the entire ` +
915	        `schema. Run \`npm run db:migrate\` instead to actually apply them.`,
916	    );
917	  }
918	
919	  if (ledger.length > 0 && !options.force) {
920	    throw new BaselineRefusedError(
921	      `Refusing to baseline: ${LEDGER_QUALIFIED} already has ${ledger.length} ` +
922	        `row(s), so this database is already adopted and the remaining ` +
923	        `migration(s) are genuinely pending. Run \`npm run db:migrate\` to ` +
924	        `apply them. Pass --force only if you are certain they are already ` +
925	        `applied by hand.`,
926	    );
927	  }
928	
929	  const missingEffects = await (options.effectVerifier ?? findMissingBaselineEffects)(
930	    client,
931	    toRecord,
932	  );
933	  if (missingEffects.length > 0) {
934	    throw new BaselineRefusedError(
935	      `Refusing to baseline: the database is missing required migration ` +
936	        `effects:\n  • ${missingEffects.join("\n  • ")}\n` +
937	        `Apply the migrations instead of recording work that has not run.`,
938	    );
939	  }
940	
941	  await ensureMigrationLedger(client);
942	
943	  await client.query("BEGIN");
944	  try {
945	    for (const filename of toRecord) {
946	      await client.query(INSERT_LEDGER_SQL, [
947	        filename,
948	        checksums.get(filename),
949	        null,
950	        true,
951	      ]);
952	    }
953	    await client.query("COMMIT");
954	  } catch (error) {
955	    await client.query("ROLLBACK").catch(() => undefined);
956	    throw error;
957	  }
958	
959	  log(
960	    `✅ Baselined ${toRecord.length} migration(s) — recorded as applied, ` +
961	      `nothing was executed.`,
962	  );
963	  return { plan, recorded: toRecord };
964	}
