970	const RULE = "═".repeat(72);
971	
972	export function formatPendingReport(plan: MigrationPlan): string[] {
973	  const lines: string[] = [];
974	
975	  if (plan.drifted.length > 0) {
976	    lines.push(RULE);
977	    lines.push(
978	      `🚨 MIGRATION CHECKSUM DRIFT — ${plan.drifted.length} applied migration ` +
979	        `file(s) changed after being applied`,
980	    );
981	    lines.push(describeDrift(plan.drifted));
982	    lines.push(
983	      `   The database was built by the OLD contents. Revert the file(s), or ` +
984	        `ship the change as a NEW migration.`,
985	    );
986	    lines.push(RULE);
987	  }
988	
989	  if (plan.pending.length > 0) {
990	    lines.push(RULE);
991	    lines.push(
992	      `⚠️  DATABASE MIGRATIONS PENDING — ${plan.pending.length} migration ` +
993	        `file(s) have never been applied to this database`,
994	    );
995	    for (const filename of plan.pending) lines.push(`   • ${filename}`);
996	    lines.push(`   Apply them with:  npm run db:migrate`);
997	    lines.push(
998	      `   Nothing was applied automatically — schema sync is never an app-start ` +
999	        `side effect (see replit.md "Data Safety Policy").`,
1000	    );
1001	    lines.push(
1002	      `   Until they are applied, any query touching a column added by them ` +
1003	        `will fail at runtime.`,
1004	    );
1005	    lines.push(RULE);
1006	  }
1007	
1008	  if (plan.orphaned.length > 0) {
1009	    lines.push(
1010	      `⚠️  ${plan.orphaned.length} migration(s) recorded but missing on disk: ` +
1011	        `${plan.orphaned.join(", ")}`,
1012	    );
1013	  }
1014	
1015	  return lines;
1016	}
1017	
1018	// ---------------------------------------------------------------------------
1019	// Startup check — read-only, non-fatal, cannot crash the server
1020	// ---------------------------------------------------------------------------
1021	
1022	export interface StartupCheckOptions {
1023	  dir?: string;
1024	  connectionString?: string;
1025	  log?: (message: string) => void;
1026	  connectionTimeoutMs?: number;
1027	  failOnIssues?: boolean;
1028	}
1029	
1030	/**
1031	 * Log loudly when migrations are pending or drifted. Never applies anything,
1032	 * never throws, never creates the ledger (a read-only check has no schema side
1033	 * effects), and swallows every failure mode including an unreachable database.
1034	 */
1035	export async function reportPendingMigrations(
1036	  options: StartupCheckOptions = {},
1037	): Promise<void> {
1038	  const log = options.log ?? ((message: string) => console.warn(message));
1039	  const failOnIssues = options.failOnIssues ?? false;
1040	  try {
1041	    const connectionString = options.connectionString ?? process.env.DATABASE_URL;
1042	    if (!connectionString) {
1043	      if (failOnIssues) throw new MigrationHistoryError("DATABASE_URL is not set");
1044	      return;
1045	    }
1046	
1047	    const dir = options.dir ?? defaultMigrationsDir();
1048	    if (!fs.existsSync(dir)) {
1049	      if (failOnIssues) throw new MigrationHistoryError(`Migrations directory not found: ${dir}`);
1050	      return;
1051	    }
1052	
1053	    let ordered: string[];
1054	    let checksums: Map<string, string>;
1055	    try {
1056	      ordered = listMigrationFiles(dir);
1057	      checksums = checksumAll(dir, ordered);
1058	    } catch (error) {
1059	      if (failOnIssues) throw error;
1060	      log(`⚠️  Migration check skipped: ${(error as Error).message}`);
1061	      return;
1062	    }
1063	    if (ordered.length === 0) {
1064	      if (failOnIssues) throw new MigrationHistoryError("No migration files found");
1065	      return;
1066	    }
1067	
1068	    // Imported lazily so a missing/broken `pg` install can never block boot.
1069	    const pg = await import("pg");
1070	    const ClientCtor = (pg as any).default?.Client ?? (pg as any).Client;
1071	    const client = new ClientCtor({
1072	      connectionString,
1073	      connectionTimeoutMillis: options.connectionTimeoutMs ?? 5_000,
1074	      statement_timeout: 5_000,
1075	      query_timeout: 5_000,
1076	      application_name: "taptpay-migration-check",
1077	    });
1078	    // A pg Client emits 'error' asynchronously; unhandled, that takes the
1079	    // process down. Absorb it here.
1080	    client.on("error", () => undefined);
1081	
1082	    try {
1083	      await client.connect();
1084	      const ledger = await readMigrationLedgerIfPresent(client as MigrationClient);
1085	      if (ledger === null) {
1086	        log(RULE);
1087	        log(
1088	          `⚠️  MIGRATION LEDGER NOT INITIALISED — ${LEDGER_QUALIFIED} does not ` +
1089	            `exist, so this database has no record of which of the ` +
1090	            `${ordered.length} checked-in migration(s) it has seen.`,
1091	        );
1092	        log(
1093	          `   If this database already has their effects:  npm run db:migrate:baseline -- --confirm`,
1094	        );
1095	        log(`   Otherwise:                                   npm run db:migrate`);
1096	        log(RULE);
1097	        if (failOnIssues) {
1098	          throw new MigrationHistoryError(`Migration ledger ${LEDGER_QUALIFIED} is not initialised`);
1099	        }
1100	        return;
1101	      }
1102	
1103	      const plan = planMigrations(ordered, checksums, ledger);
1104	      const lines = formatPendingReport(plan);
1105	      if (lines.length === 0) {
1106	        console.log(
1107	          `✅ Migrations: all ${plan.applied.length} applied (${LEDGER_QUALIFIED})`,
1108	        );
1109	        return;
1110	      }
1111	      for (const line of lines) log(line);
1112	      if (failOnIssues && (
1113	        plan.drifted.length > 0 || plan.pending.length > 0 ||
1114	        plan.orphaned.length > 0 || plan.outOfOrder.length > 0
1115	      )) {
1116	        throw new MigrationHistoryError(
1117	          `Database migration gate failed: ${plan.pending.length} pending, ${plan.drifted.length} drifted, ${plan.orphaned.length} orphaned, ${plan.outOfOrder.length} out of order`,
1118	        );
1119	      }
1120	    } finally {
1121	      try {
1122	        await client.end();
1123	      } catch {
1124	        // Closing a never-opened or already-broken connection is not a problem.
1125	      }
1126	    }
1127	  } catch (error) {
1128	    // Never fatal: a migration check must not be able to stop the server.
1129	    log(`⚠️  Migration check failed (non-fatal): ${(error as Error).message}`);
1130	    if (failOnIssues) throw error;
1131	  }
1132	}
1133	
1134	// ---------------------------------------------------------------------------
1135	// CLI
1136	// ---------------------------------------------------------------------------
1137	
1138	export interface CliOptions {
1139	  mode: "apply" | "status" | "baseline";
1140	  dryRun: boolean;
1141	  confirm: boolean;
1142	  force: boolean;
1143	  unknown: string[];
1144	}
1145	
1146	export function parseCliArgs(argv: readonly string[]): CliOptions {
1147	  const options: CliOptions = {
1148	    mode: "apply",
1149	    dryRun: false,
1150	    confirm: false,
1151	    force: false,
1152	    unknown: [],
1153	  };
1154	  for (const arg of argv) {
1155	    switch (arg) {
1156	      case "--baseline":
1157	        options.mode = "baseline";
1158	        break;
1159	      case "--status":
1160	        options.mode = "status";
1161	        break;
1162	      case "--dry-run":
1163	        options.dryRun = true;
1164	        break;
1165	      case "--confirm":
1166	        options.confirm = true;
1167	        break;
1168	      case "--force":
1169	        options.force = true;
1170	        break;
1171	      default:
1172	        options.unknown.push(arg);
1173	    }
1174	  }
1175	  return options;
1176	}
1177	
1178	async function main(): Promise<void> {
1179	  const options = parseCliArgs(process.argv.slice(2));
1180	  if (options.unknown.length > 0) {
1181	    console.error(`Unknown argument(s): ${options.unknown.join(", ")}`);
1182	    console.error(
1183	      `Usage: tsx server/migrate.ts [--status | --dry-run | --baseline [--confirm] [--force]]`,
1184	    );
1185	    process.exit(2);
1186	  }
1187	
1188	  const connectionString = process.env.DATABASE_URL;
1189	  if (!connectionString) {
1190	    console.error("DATABASE_URL is not set — refusing to run migrations.");
1191	    process.exit(1);
1192	  }
1193	
1194	  const pg = await import("pg");
1195	  const ClientCtor = (pg as any).default?.Client ?? (pg as any).Client;
1196	  const client = new ClientCtor({
1197	    connectionString,
1198	    application_name: "taptpay-migrate",
1199	  });
1200	  client.on("error", (error: unknown) => {
1201	    console.error("Database connection error:", error);
1202	  });
1203	
1204	  const target = (() => {
1205	    try {
1206	      const parsed = new URL(connectionString);
1207	      return `${parsed.hostname}${parsed.port ? `:${parsed.port}` : ""}${parsed.pathname}`;
1208	    } catch {
1209	      return "(unparseable DATABASE_URL)";
1210	    }
1211	  })();
1212	  console.log(`Migration runner → ${target}`);
1213	
1214	  await client.connect();
1215	  try {
1216	    if (options.mode === "status") {
1217	      const dir = defaultMigrationsDir();
1218	      const ordered = listMigrationFiles(dir);
1219	      const checksums = checksumAll(dir, ordered);
1220	      const ledger = await readMigrationLedgerIfPresent(client as MigrationClient);
1221	      if (ledger === null) {
1222	        console.log(
1223	          `Ledger ${LEDGER_QUALIFIED} does not exist — no migrations recorded.`,
1224	        );
1225	        console.log(`${ordered.length} migration file(s) on disk:`);
1226	        for (const filename of ordered) console.log(`  • ${filename} (unrecorded)`);
1227	        process.exitCode = 1;
1228	        return;
1229	      }
1230	      const plan = planMigrations(ordered, checksums, ledger);
1231	      console.log(
1232	        `${plan.applied.length} applied, ${plan.pending.length} pending, ` +
1233	          `${plan.drifted.length} drifted, ${plan.orphaned.length} orphaned.`,
1234	      );
1235	      const lines = formatPendingReport(plan);
1236	      for (const line of lines) console.log(line);
1237	      if (
1238	        plan.drifted.length > 0 ||
1239	        plan.pending.length > 0 ||
1240	        plan.orphaned.length > 0 ||
1241	        plan.outOfOrder.length > 0
1242	      ) process.exitCode = 1;
1243	      return;
1244	    }
1245	
1246	    if (options.mode === "baseline") {
1247	      await withMigrationAdvisoryLock(client as MigrationClient, () =>
1248	        baselineMigrations(client as MigrationClient, {
1249	          confirm: options.confirm,
1250	          force: options.force,
1251	        }),
1252	      );
1253	      return;
1254	    }
1255	
1256	    await withMigrationAdvisoryLock(client as MigrationClient, () =>
1257	      runPendingMigrations(client as MigrationClient, { dryRun: options.dryRun }),
1258	    );
1259	  } finally {
1260	    await client.end().catch(() => undefined);
1261	  }
1262	}
1263	
1264	/**
1265	 * Run only when this file is the process entrypoint. Deliberately avoids
1266	 * `import.meta` so the module still loads under ts-jest's CommonJS transform.
1267	 */
1268	const entrypoint = process.argv[1] ?? "";
1269	const isDirectInvocation =
1270	  /(^|[\\/])migrate\.(?:ts|js|mjs|cjs)$/.test(entrypoint) &&
1271	  !process.env.JEST_WORKER_ID;
1272	
1273	if (isDirectInvocation) {
1274	  main().catch((error: unknown) => {
1275	    console.error("");
